SELECT COALESCE(MAX(FORM_VER_NO), 0)
  FROM SVC_REQ_FORM_TMPL
 WHERE CAT_SN = #{catSn}

mapper.update:
UPDATE SVC_REQ_FORM_TMPL
   SET FORM_USE_YN = 'N',
       FORM_UPDT_DT = CURRENT_TIMESTAMP,
       FORM_UPDT_ID = #{actorId}
 WHERE CAT_SN = #{catSn}
   AND FORM_ACTV_YN = 'N'
   AND FORM_USE_YN = 'Y'
   AND FORM_VER_NO > #{activeVersion}

mapper.insert:
INSERT INTO SVC_REQ_FORM_TMPL (
    CAT_SN, FORM_VER_NO, FIRST_STEP_SN, FORM_SUBTTL, FORM_UI_META_JSON,
    FORM_ACTV_YN, FORM_USE_YN, FORM_REG_ID, FORM_UPDT_ID
) VALUES (
    #{form.catSn}, #{form.formVersion}, NULL, #{form.subtitle},

        CAST(#{form.uiMetaJson} AS JSON)
        NULL
    ,
    'N', 'Y', #{actorId}, #{actorId}
)

