UPDATE SVC_REQ_STEP_DEF
   SET NEXT_STEP_SN = #{nextStepSn},
       SVC_REQ_STEP_UPDT_DT = CURRENT_TIMESTAMP,
       SVC_REQ_STEP_UPDT_ID = #{actorId}
 WHERE SVC_REQ_FORM_TMPL_SN = #{formTemplateSn}
   AND SVC_REQ_STEP_SN = #{stepSn}

UPDATE SVC_REQ_FORM_TMPL
   SET FIRST_STEP_SN = #{firstStepSn},
       FORM_UPDT_DT = CURRENT_TIMESTAMP,
       FORM_UPDT_ID = #{actorId}
 WHERE SVC_REQ_FORM_TMPL_SN = #{formTemplateSn}

